<script setup lang="ts">import{computed,onBeforeUnmount,onMounted,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{useCafe}from'@/stores/cafe';import{steps,labels}from'@/constants/menu';import{num,price}from'@/utils/format';import type{Order}from'@/types/cafe';const store=useCafe(),route=useRoute(),router=useRouter(),order=ref<Order|null>(null),loading=ref(true),index=computed(()=>Math.max(0,steps.indexOf(order.value?.status??'new')));async function refresh(){order.value=await store.getOrder(String(route.params.id));loading.value=false}let timer:ReturnType<typeof setInterval>;onMounted(async()=>{await refresh();timer=setInterval(refresh,4000)});onBeforeUnmount(()=>clearInterval(timer));async function again(){store.reset();await router.push({name:'menu',query:{table:order.value?.table??1}})}</script><template><div v-if="loading" class="loading-state">جاري تحميل حالة الطلب…</div><template v-else-if="order"><section class="done"><div class="big">✓</div><h1>تم إرسال طلبك!</h1><p>وصل طلبك إلى المقهى وسيبدأ التحضير قريبًا</p><span class="rf">رقم الطلب: #{{order.ref}} • طاولة {{num(order.table)}} • {{price(order.items.reduce((s,x)=>s+x.pr*x.q,0))}}</span></section><section class="status-track"><div v-for="(s,i) in steps" :key="s" class="stp2" :class="{on:i<=index}"><span class="d">{{i<index?'✓':num(i+1)}}</span><span><b>{{labels[s][0]}}</b><small>{{labels[s][1]}}</small></span></div></section><div class="order-actions"><button class="btn-g secondary" @click="again">＋ طلب المزيد</button></div><p class="refresh-note">تتحدث حالة الطلب تلقائيًا — لا تُغلق الصفحة</p></template><section v-else class="empty-state"><h2>الطلب غير موجود</h2><RouterLink to="/">العودة للبداية</RouterLink></section></template>
